from pathlib import Path
R=Path('.')
def repl(path,old,new):
 p=R/path; s=p.read_text(); n=s.count(old)
 if n!=1: raise SystemExit(f'{path}:match={n}')
 p.write_text(s.replace(old,new))
repl('core/planning.py','''    def build(self, task: TaskSpec) -> Plan:\n        if not isinstance(task, TaskSpec) or not task.is_well_formed():\n            raise TypeError("task must be a well-formed TaskSpec")\n        step = PlanStep(f"{task.task_id}:0", task.objective, "compute", task.risk_class)\n        return Plan(task.task_id, (step,))\n''','''    def build(self, task: TaskSpec) -> Plan:\n        if not isinstance(task, TaskSpec) or not task.is_well_formed():\n            raise TypeError("task must be a well-formed TaskSpec")\n        dual = isinstance(task.constraints, dict) and bool(task.constraints.get("noryx7_dual_agent"))\n        if dual:\n            return Plan(task.task_id, (\n                PlanStep(f"{task.task_id}:0", task.objective, "compute", task.risk_class),\n                PlanStep(f"{task.task_id}:1", "Independently review, cross-check and improve the primary reasoning for: " + task.objective, "compute", task.risk_class),\n            ))\n        step = PlanStep(f"{task.task_id}:0", task.objective, "compute", task.risk_class)\n        return Plan(task.task_id, (step,))\n''')
