Path('core/web_research.py').write_text('''from __future__ import annotations\nfrom dataclasses import dataclass,asdict\nfrom datetime import datetime,timezone\nimport html,re\nfrom urllib.parse import quote,urljoin\nfrom urllib.request import Request,urlopen\n@dataclass(frozen=True)\nclass ResearchSource:\n url:str; title:str; snippet:str; retrieved_at:str; status:str\nclass WebResearchEngine:\n MAX_RESULTS=5; MAX_BYTES=750_000; TIMEOUT=8\n TRIGGERS=("latest","today","current","recent","news","research","source","sources","evidence","verify","internet","web","online","live","prezzo","price","mercato","normativa")\n def should_research(self,task):\n  text=" ".join(str(x or "") for x in (getattr(task,"objective",""),getattr(task,"input",""))).lower(); return any(t in text for t in self.TRIGGERS)\n def _fetch(self,q):\n  req=Request("https://html.duckduckgo.com/html/?q="+quote(q,safe=""),headers={"User-Agent":"NORYX7/1.0 research"})\n  with urlopen(req,timeout=self.TIMEOUT) as r: data=r.read(self.MAX_BYTES+1)\n  if len(data)>self.MAX_BYTES: raise ValueError("research_response_limit_exceeded")\n  return data.decode("utf-8","replace")\n def search(self,q):\n  try: page=self._fetch(q)\n  except Exception: return ()\n  now=datetime.now(timezone.utc).isoformat(); out=[]; pat=re.compile(r'<a[^>]+class="result__a"[^>]+href="([^"]+)"[^>]*>(.*?)</a>',re.I|re.S)\n  for m in pat.finditer(page):\n   href,title=m.groups(); title=html.unescape(re.sub(r"<[^>]+>","",title)).strip(); c=page[m.end():m.end()+2500]; sm=re.search(r'class="result__snippet"[^>]*>(.*?)</(?:a|div)>',c,re.I|re.S); sn=html.unescape(re.sub(r"<[^>]+>","",sm.group(1) if sm else "")).strip()\n   if href.startswith("//"): href="https:"+href\n   elif href.startswith("/"): href=urljoin("https://html.duckduckgo.com",href)\n   if not href.startswith("http") or not title: continue\n   out.append(ResearchSource(href,title[:300],sn[:600],now,"retrieved"))\n   if len(out)>=self.MAX_RESULTS: break\n  return tuple(out)\n def run(self,task):\n  if not self.should_research(task): return {"enabled":False,"query":None,"sources":(),"status":"not_needed"}\n  q=f"{getattr(task,'objective','')} {getattr(task,'input','')}".strip()[:1000]; s=self.search(q); return {"enabled":True,"query":q,"sources":tuple(asdict(x) for x in s),"status":"ok" if s else "unavailable"}\n''')
Path('tests/test_frontier_integration.py').write_text('''from core.planning import Planner\nfrom core.contracts import TaskSpec\nfrom core.web_research import WebResearchEngine\ndef t(c=None): return TaskSpec("t1","analysis","latest NORYX7 architecture","check current sources",c or {},{},"normal","exec1")\ndef test_dual_agent_plan(): assert len(Planner(max_steps=2).build(t({"noryx7_dual_agent":True})).steps)==2\ndef test_research_trigger(): assert WebResearchEngine().should_research(t())\ndef test_research_not_needed(): assert WebResearchEngine().run(TaskSpec("t2","analysis","summarize this text","hello",{},{},"normal","exec2"))["status"]=="not_needed"\n''')
